const body = $input.first().json.body ?? $input.first().json;
const trace_id = body.trace_id ?? 'no-trace-id';
const payload = body.event?.payload ?? {};
const LETTA_URL = 'http://letta:8283';
const AGENT_ID = 'agent-9972f1c0-0dd2-4ebc-be75-fba370d1f70b';

try {
  const content = payload.content || '';
  const mode = payload.mode || 'append';
  const block = payload.block || 'human';

  if (!content) {
    return [{ json: { ok: false, trace_id, error: { message: 'No content provided', node: 'memory.write' } } }];
  }

  let newValue = content;

  if (mode === 'append') {
    const current = await helpers.httpRequest({
      url: LETTA_URL + '/v1/agents/' + AGENT_ID + '/core-memory',
      method: 'GET',
      json: true
    });
    const blocks = current.blocks || [];
    const targetBlock = blocks.find(function(b) { return b.label === block; });
    const currentValue = targetBlock ? targetBlock.value : '';
    newValue = currentValue + '\n' + content;
  }

  const res = await helpers.httpRequest({
    url: LETTA_URL + '/v1/agents/' + AGENT_ID + '/core-memory/blocks/' + block,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: { value: newValue },
    json: true
  });

  return [{ json: { ok: true, trace_id, result: { agent_id: AGENT_ID, block: block, mode: mode, value: res.value } } }];
} catch (err) {
  return [{ json: { ok: false, trace_id, error: { message: err.message, node: 'memory.write', details: String(err) } } }];
}

